using EduManageLms.Api.Application; using EduManageLms.Api.Common; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace EduManageLms.Api.Controllers; [ApiController][Route("api/v1/admin")][Authorize(Roles="Admin")]
public sealed class AdminController(IAdminResourceService svc,IBackupService backups):ControllerBase{[HttpGet("{resource:regex(^(users|students|lecturers|courses|class-sections)$)}")]public async Task<ActionResult<ApiResponse<PagedResult<Dictionary<string,object?>>>>> List(string resource,[FromQuery]string? search,[FromQuery]int pageNumber=1,[FromQuery]int pageSize=20,CancellationToken ct=default)=>Ok(ApiResponse<PagedResult<Dictionary<string,object?>>>.Ok(await svc.ListAsync(resource,search,Math.Max(1,pageNumber),Math.Clamp(pageSize,1,100),ct)));[HttpPost("{resource:regex(^(users|students|lecturers|courses|class-sections)$)}")]public async Task<ActionResult<ApiResponse<Dictionary<string,object?>>>> Create(string resource,Dictionary<string,object?> body,CancellationToken ct)=>Ok(ApiResponse<Dictionary<string,object?>>.Ok(await svc.CreateAsync(resource,body,ct),"Tạo dữ liệu thành công"));[HttpPut("{resource:regex(^(users|students|lecturers|courses|class-sections)$)}/{id}")]public async Task<ActionResult<ApiResponse<Dictionary<string,object?>>>> Update(string resource,string id,Dictionary<string,object?> body,CancellationToken ct)=>Ok(ApiResponse<Dictionary<string,object?>>.Ok(await svc.UpdateAsync(resource,id,body,ct),"Cập nhật thành công"));[HttpDelete("{resource:regex(^(users|students|lecturers|courses|class-sections)$)}/{id}")]public async Task<ActionResult<ApiResponse<object>>> Delete(string resource,string id,CancellationToken ct){await svc.DeleteAsync(resource,id,ct);return Ok(ApiResponse<object>.Ok(new{},"Xóa mềm thành công"));}[HttpGet("backups")]public async Task<ActionResult<ApiResponse<IReadOnlyCollection<Dictionary<string,object?>>>>> BackupList(CancellationToken ct)=>Ok(ApiResponse<IReadOnlyCollection<Dictionary<string,object?>>>.Ok(await backups.ListAsync(ct)));[HttpPost("backups")]public async Task<ActionResult<ApiResponse<Dictionary<string,object>>>> Backup(CancellationToken ct)=>Ok(ApiResponse<Dictionary<string,object>>.Ok(await backups.CreateAsync(User.UserId(),ct),"Sao lưu thành công"));[HttpPost("backups/{id}/restore")]public async Task<ActionResult<ApiResponse<object>>> Restore(string id,[FromBody]Dictionary<string,string> body,CancellationToken ct){await backups.RestoreAsync(id,User.UserId(),body.GetValueOrDefault("confirmation",string.Empty),ct);return Ok(ApiResponse<object>.Ok(new{},"Phục hồi thành công"));}}
